<?php
require_once 'config.php';require_role(['admin']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pid=(int)$_POST['product_id'];$qty=(int)$_POST['qty'];$type=$_POST['movement_type'];$note=trim($_POST['note']??'');
 if($qty<1||!in_array($type,['masuk','keluar'],true)){flash('Data stok tidak valid.','error');}
 else{try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT stock FROM products WHERE id=? FOR UPDATE');$q->execute([$pid]);$p=$q->fetch();if(!$p)throw new Exception('Menu tidak ditemukan.');if($type==='keluar'&&$p['stock']<$qty)throw new Exception('Stok tidak mencukupi.');$delta=$type==='masuk'?$qty:-$qty;$pdo->prepare('UPDATE products SET stock=stock+? WHERE id=?')->execute([$delta,$pid]);$pdo->prepare('INSERT INTO stock_movements(product_id,movement_type,qty,note,user_id) VALUES(?,?,?,?,?)')->execute([$pid,$type,$qty,$note,$_SESSION['user']['id']]);$pdo->commit();flash('Stok berhasil diperbarui.');}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();flash($x->getMessage(),'error');}}
 header('Location: stock.php');exit;}
$products=$pdo->query('SELECT * FROM products WHERE active=1 ORDER BY name')->fetchAll();
$movements=$pdo->query('SELECT m.*,p.name product,u.name user_name FROM stock_movements m JOIN products p ON p.id=m.product_id JOIN users u ON u.id=m.user_id ORDER BY m.id DESC LIMIT 15')->fetchAll();
$page='stock';include 'partials/header.php';
?>
<section class="page-heading"><div><p class="eyebrow">PENGELOLAAN PERSEDIAAN</p><h1>Pengelolaan Stok</h1><p class="muted">Catat stok masuk dan keluar bahan/menu.</p></div></section>
<section class="panel"><h3>Perbarui Stok</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div><label>Menu</label><select name="product_id" required><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> (stok <?=$p['stock']?>)</option><?php endforeach;?></select></div><div><label>Jenis pergerakan</label><select name="movement_type"><option value="masuk">Stok masuk</option><option value="keluar">Stok keluar</option></select></div><div><label>Jumlah</label><input type="number" name="qty" min="1" required></div><div><label>Catatan</label><input name="note" placeholder="Contoh: pembelian dari pemasok"></div><div class="form-action"><button class="btn primary">Simpan Perubahan</button></div></form></section>
<section class="panel"><h3>Posisi Stok</h3><div class="table-wrap"><table><thead><tr><th>Menu</th><th>Harga Jual</th><th>Stok</th><th>Status</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=rupiah($p['sell_price'])?></td><td><?=$p['stock']?></td><td><span class="stock-badge <?=$p['stock']<=5?'low':''?>"><?=$p['stock']<=5?'Menipis':'Tersedia'?></span></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h3>Riwayat Perubahan Stok</h3><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Menu</th><th>Jenis</th><th>Jumlah</th><th>Catatan</th><th>Petugas</th></tr></thead><tbody><?php foreach($movements as $m):?><tr><td><?=date('d/m/Y H:i',strtotime($m['created_at']))?></td><td><?=e($m['product'])?></td><td><?=e(ucfirst($m['movement_type']))?></td><td><?=$m['qty']?></td><td><?=e($m['note'])?></td><td><?=e($m['user_name'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php include 'partials/footer.php';?>
